<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/config/database.php';
require_once dirname(__DIR__, 2) . '/includes/auth.php';
requireAdmin();
$errors = []; $notice = ''; $edit = null;
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    if (!verifyCsrfToken()) $errors[] = 'Permintaan tidak valid. Silakan coba lagi.';
    else {
        $action = (string) ($_POST['action'] ?? ''); $id = (int) ($_POST['ruangan_id'] ?? 0);
        if ($action === 'delete' && $id > 0) {
            $check = $pdo->prepare('SELECT COUNT(*) FROM lemari WHERE ruangan_id = :id'); $check->execute(['id' => $id]);
            if ((int) $check->fetchColumn() > 0) $errors[] = 'Ruangan masih memiliki lemari dan tidak dapat dihapus.';
            else { $pdo->prepare('DELETE FROM ruangan WHERE ruangan_id = :id')->execute(['id' => $id]); logActivity($pdo, (int) $_SESSION['user_id'], 'DELETE'); $notice = 'Ruangan berhasil dihapus.'; }
        }
        if (in_array($action, ['create', 'update'], true)) {
            $values = ['unit_id' => (int) ($_POST['unit_id'] ?? 0), 'kode_ruangan' => trim((string) ($_POST['kode_ruangan'] ?? '')), 'nama_ruangan' => trim((string) ($_POST['nama_ruangan'] ?? '')), 'keterangan' => trim((string) ($_POST['keterangan'] ?? ''))];
            if ($values['unit_id'] === 0 || $values['kode_ruangan'] === '' || $values['nama_ruangan'] === '') $errors[] = 'Unit kerja, kode, dan nama ruangan wajib diisi.';
            $unit = $pdo->prepare('SELECT unit_id FROM unit_kerja WHERE unit_id = :id'); $unit->execute(['id' => $values['unit_id']]); if (!$unit->fetch()) $errors[] = 'Unit kerja tidak valid.';
            $exists = $pdo->prepare('SELECT ruangan_id FROM ruangan WHERE unit_id = :unit_id AND kode_ruangan = :kode_ruangan AND ruangan_id != :id'); $exists->execute(['unit_id' => $values['unit_id'], 'kode_ruangan' => $values['kode_ruangan'], 'id' => $id]); if ($exists->fetch()) $errors[] = 'Kode ruangan sudah digunakan pada unit kerja ini.';
            if (!$errors && $action === 'create') { $pdo->prepare('INSERT INTO ruangan (unit_id, kode_ruangan, nama_ruangan, keterangan) VALUES (:unit_id, :kode_ruangan, :nama_ruangan, :keterangan)')->execute($values); logActivity($pdo, (int) $_SESSION['user_id'], 'CREATE'); $notice = 'Ruangan berhasil ditambahkan.'; }
            if (!$errors && $action === 'update' && $id > 0) { $pdo->prepare('UPDATE ruangan SET unit_id=:unit_id, kode_ruangan=:kode_ruangan, nama_ruangan=:nama_ruangan, keterangan=:keterangan WHERE ruangan_id=:id')->execute($values + ['id' => $id]); logActivity($pdo, (int) $_SESSION['user_id'], 'UPDATE'); $notice = 'Ruangan berhasil diperbarui.'; }
        }
    }
}
if (isset($_GET['edit'])) { $statement = $pdo->prepare('SELECT ruangan_id, unit_id, kode_ruangan, nama_ruangan, keterangan FROM ruangan WHERE ruangan_id=:id'); $statement->execute(['id'=>(int) $_GET['edit']]); $edit = $statement->fetch() ?: null; }
$units = $pdo->query('SELECT unit_id, kode_unit, nama_unit FROM unit_kerja ORDER BY nama_unit')->fetchAll();
$query = trim((string) ($_GET['q'] ?? '')); $statement = $pdo->prepare('SELECT r.ruangan_id,r.unit_id,r.kode_ruangan,r.nama_ruangan,r.keterangan,u.nama_unit,(SELECT COUNT(*) FROM lemari l WHERE l.ruangan_id=r.ruangan_id) AS cabinet_count FROM ruangan r INNER JOIN unit_kerja u ON u.unit_id=r.unit_id WHERE r.kode_ruangan LIKE :code OR r.nama_ruangan LIKE :name OR u.nama_unit LIKE :unit ORDER BY u.nama_unit,r.nama_ruangan'); $statement->execute(['code'=>"%{$query}%",'name'=>"%{$query}%",'unit'=>"%{$query}%"]); $rooms = $statement->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><?php require dirname(__DIR__, 2) . '/includes/favicon.php'; ?><title>Ruangan | e-ARSIP KAI Divre III</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Material+Symbols+Outlined" rel="stylesheet"><link rel="stylesheet" href="../../assets/css/auth.css"></head><body class="dashboard-body"><aside class="admin-sidebar"><div class="brand"><img src="../../assets/images/logo_kai.svg" alt="Logo KAI"><div><strong>e-ARSIP</strong><strong>KAI DIVRE III</strong><small>Web Pengarsipan Digital</small></div></div><nav><p>Menu Administrasi</p><a href="../../dashboard.php?role=admin"><i class="material-symbols-outlined">dashboard</i>Dashboard</a><a href="users.php"><i class="material-symbols-outlined">group</i>Pengelolaan Pengguna</a><p>Master Data</p><a href="unit.php"><i class="material-symbols-outlined">domain</i>Unit Kerja</a><span class="nav-active"><i class="material-symbols-outlined">meeting_room</i>Ruangan</span></nav></aside><div class="admin-main"><header class="admin-header"><div><b>Ruangan</b><small>Master data lokasi penyimpanan</small></div><details class="user-menu"><summary><span class="user-avatar"><?=e(strtoupper(substr((string)($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'U'),0,1)))?></span><span class="user-summary-text"><b><?=e((string)($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'User'))?></b><small><?=e((string)($_SESSION['role_name'] ?? 'Admin'))?></small></span><i class="user-summary-chevron material-symbols-outlined">expand_more</i></summary><div class="user-dropdown"><div class="user-dropdown-header"><b><?=e((string)($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'User'))?></b><small><?=e((string)($_SESSION['role_name'] ?? 'Admin'))?></small></div><a href="../../logout.php"><i class="material-symbols-outlined">logout</i>Logout</a></div></details></header><main class="admin-content"><?php if ($notice): ?><p class="notice"><?= e($notice) ?></p><?php endif; ?><?php if ($errors): ?><div class="alert"><?php foreach ($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><section class="panel master-form"><h2><?= $edit ? 'Edit Ruangan' : 'Tambah Ruangan' ?></h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="<?= $edit ? 'update' : 'create' ?>"><?php if ($edit): ?><input type="hidden" name="ruangan_id" value="<?= (int) $edit['ruangan_id'] ?>"><?php endif; ?><label>Unit Kerja<select name="unit_id" required><option value="">Pilih unit kerja</option><?php foreach ($units as $unit): ?><option value="<?= (int) $unit['unit_id'] ?>" <?= (int) ($edit['unit_id'] ?? 0) === (int) $unit['unit_id'] ? 'selected' : '' ?>><?= e($unit['kode_unit'].' - '.$unit['nama_unit']) ?></option><?php endforeach; ?></select></label><label>Kode Ruangan<input name="kode_ruangan" maxlength="50" required value="<?= e($edit['kode_ruangan'] ?? '') ?>"></label><label>Nama Ruangan<input name="nama_ruangan" maxlength="100" required value="<?= e($edit['nama_ruangan'] ?? '') ?>"></label><label>Keterangan<textarea name="keterangan" maxlength="255"><?= e($edit['keterangan'] ?? '') ?></textarea></label><div><button class="primary-button" type="submit"><?= $edit ? 'Simpan Perubahan' : 'Tambah Ruangan' ?></button><?php if ($edit): ?><a href="ruangan.php">Batal</a><?php endif; ?></div></form></section><section class="panel user-list"><h2>Daftar Ruangan</h2><form method="get" class="filter-form"><input name="q" value="<?= e($query) ?>" placeholder="Cari unit, kode, atau nama ruangan"><button type="submit">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Unit Kerja</th><th>Kode</th><th>Nama Ruangan</th><th>Lemari</th><th>Keterangan</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rooms as $room): ?><tr><td><?= e($room['nama_unit']) ?></td><td><?= e($room['kode_ruangan']) ?></td><td><?= e($room['nama_ruangan']) ?></td><td><?= (int) $room['cabinet_count'] ?></td><td><?= e($room['keterangan'] ?? '-') ?></td><td><a href="ruangan.php?edit=<?= (int) $room['ruangan_id'] ?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="ruangan_id" value="<?= (int) $room['ruangan_id'] ?>"><button type="submit">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></main></div></body></html>
